import React, { useState } from 'react';

import PohAlert from '@ui-kit/Alert';
import PohSelect from '@ui-kit/Select';

import { getRecipeCategories } from '../../@services/recipes.service';
import { IRecipeCategory } from '../../@types/recipes.types';

interface ISelectRecipeCategoryProps {
  value?: IRecipeCategory['id'];
  onChange: (selectedCategory: IRecipeCategory | null) => void;
}

const SelectRecipeCategory: React.FC<ISelectRecipeCategoryProps> = ({ value, onChange }) => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [err, setErr] = React.useState<Error>();

  const [categories, setCategories] = useState<IRecipeCategory[]>([]);

  React.useEffect(() => {
    const start = async () => {
      try {
        setIsLoading(true);
        const res = await getRecipeCategories();
        setCategories(res);
      } catch (e) {
        setErr(e as Error);
      } finally {
        setIsLoading(false);
      }
    };

    start();
  }, []);

  if (err) {
    return <PohAlert>{err.message}</PohAlert>;
  }

  return (
    <PohSelect<number>
      horizontal
      options={
        categories.map((cat) => {
          return {
            value: cat.id,
            label: cat.name,
          };
        }) || []
      }
      disabled={isLoading}
      label="Категория"
      labelClassName="text-end"
      placeholder="Категория рецепта"
      required
      value={value}
      onChange={(v) =>
        onChange(categories.find((cat) => cat.id.toString() === v.toString()) ?? null)
      }
    />
  );
};

export default SelectRecipeCategory;
